        novas = [f"comissoes.{acao}" for acao in ("ver", "editar")
                 if f"contas_pagar.{acao}" in atuais and f"comissoes.{acao}" not in atuais]
        if novas:
            conn.execute(perfis.update().where(perfis.c.id == pid).values(permissoes=sorted(atuais + novas)))


